RuleIntegral integrate_once(
    const CurrentElement &source,
    const std::array<Point, 4> &vertices,
    const Point &target,
    int order,
    WorkBudget &work,
    const mfem::IntegrationRule *ci_rule = nullptr,
    double *ci_minimum_distance = nullptr)
#else

#ifdef FULLMAG_DTQ_CI_LEAF_DIAGNOSTIC
    const auto &rules = ci_rule != nullptr ? *ci_rule : mfem::IntRules.Get(mfem::Geometry::TETRAHEDRON, order);
