#ifdef FULLMAG_DTQ_CI_LEAF_DIAGNOSTIC
// Private fixed-size handoff for this CI-only contract executable.
struct CiLeafSnapshot {
    Leaf leaf{};
    CurrentElement::FrozenInput source{};
};
struct CiLeafDiagnosticState {
    std::array<CiLeafSnapshot, 3> snapshots{};
    Point target{};
    DirectTetraQuadratureOptions options{};
    std::size_t count = 0;
    std::uint64_t consumed_leaves = 0;
    std::uint64_t kernel_evaluations = 0;
    bool capture_failed = false;
    bool armed = false;
};
constexpr std::uint64_t kCiSamplesPerLeaf = 10374;
constexpr std::uint64_t kCiMaximumLeaves = 12;
constexpr std::uint64_t kCiMaximumSamples = 124488;
static_assert(kCiSamplesPerLeaf * kCiMaximumLeaves == kCiMaximumSamples);

CiLeafDiagnosticState &ci_leaf_diagnostic_state()
{
    // Each CI caller owns its state; only the standalone main explicitly arms its thread.
    static thread_local CiLeafDiagnosticState state;
    return state;
}

void capture_ci_leaf_snapshots(const std::vector<PreparedElement> &elements,
    const std::vector<Leaf> &leaves, const Point &target,
    const DirectTetraQuadratureOptions &options) noexcept
{
    auto &state = ci_leaf_diagnostic_state();
    if (!state.armed) return;
    state.count = 0;
    state.capture_failed = false;
    try {
        std::array<const Leaf *, 3> top{};
        for (const auto &leaf : leaves) {
            for (std::size_t rank = 0; rank < top.size(); ++rank) {
                if (top[rank] == nullptr || leaf.error > top[rank]->error ||
                        (leaf.error == top[rank]->error && leaf.sequence < top[rank]->sequence)) {
                    for (std::size_t next = top.size() - 1; next > rank; --next) {
                        top[next] = top[next - 1];
                    }
                    top[rank] = &leaf;
                    break;
                }
            }
        }
        state.target = target;
        state.options = options;
        for (const auto *leaf : top) {
            if (leaf == nullptr) continue;
            state.snapshots[state.count] = {*leaf, elements.at(leaf->source_index).current.frozen_input()};
            ++state.count;
        }
    } catch (...) {
        state.count = 0;
        state.capture_failed = true;
    }
}

void replay_ci_leaf_snapshots()
{
    auto &state = ci_leaf_diagnostic_state();
    if (!state.armed) return;
    const auto snapshots = state.snapshots;
    const auto count = state.count;
    const auto target = state.target;
    const auto options = state.options;
    const bool capture_failed = state.capture_failed;
    state.count = 0;
    state.capture_failed = false;
    if (capture_failed) {
        std::cerr << "OE-F1 LEAF_DIAGNOSTIC NOT_COMPARABLE reason=capture_failed\n";
        return;
    }
    for (std::size_t rank = 0; rank < count; ++rank) {
        if (state.consumed_leaves >= kCiMaximumLeaves || state.kernel_evaluations >= kCiMaximumSamples) {
            std::cerr << "OE-F1 LEAF_DIAGNOSTIC NOT_COMPARABLE reason=executable_cap\n";
            break;
        }
        ++state.consumed_leaves;
        const auto &snapshot = snapshots[rank];
        const auto &leaf = snapshot.leaf;
        std::ostringstream text;
        text.imbue(std::locale::classic());
        text << std::hexfloat;
        const auto point = [&text](const Point &value) {
            text << '(' << value[0] << ',' << value[1] << ',' << value[2] << ')';
        };
        text << "OE-F1 LEAF_DIAGNOSTIC SNAPSHOT rank=" << rank << " target_m=";
        point(target);
        text << " source=" << leaf.source_index << " sequence=" << leaf.sequence
             << " depth=" << leaf.depth << " needs_refine=" << leaf.needs_refine << " vertices_m=";
        for (const auto &vertex : leaf.vertices) point(vertex);
        text << " source_vertices_m=";
        for (const auto &vertex : snapshot.source.vertices_m) point(vertex);
        text << " source_signed_coefficients_a=(";
        for (const auto value : snapshot.source.signed_coefficients_a) text << value << ',';
        text << ") retained_high_apm=";
        point(leaf.high);
        text << " retained_error_apm=" << leaf.error << " retained_weighted_norm=" << leaf.weighted_norm_sum;
        const auto a = subtract(leaf.vertices[1], leaf.vertices[0]);
        const auto b = subtract(leaf.vertices[2], leaf.vertices[0]);
        const auto c = subtract(leaf.vertices[3], leaf.vertices[0]);
        const auto offset = subtract(target, leaf.vertices[0]);
        const double det = determinant(a, b, c);
        const double b1 = determinant(offset, b, c) / det;
        const double b2 = determinant(a, offset, c) / det;
        const double b3 = determinant(a, b, offset) / det;
        text << " determinant_m3=" << det << " barycentric_before_snap=("
             << 1.0 - b1 - b2 - b3 << ',' << b1 << ',' << b2 << ',' << b3 << ')';
        Point effective_target{};
        std::array<std::array<Point, 4>, 4> children{};
        int child_count = 0;
        const bool duffy = decompose_target_tetrahedron(leaf.vertices, target,
            &effective_target, &children, &child_count);
        text << " classification=" << (leaf.needs_refine ? 'U' : duffy ? 'D' : 'R') << '\n';
        if (leaf.needs_refine || duffy || leaf.depth != 6 || options.base_quadrature_order != 8 ||
                !std::isfinite(det) || det == 0.0) {
            text << "OE-F1 LEAF_DIAGNOSTIC NOT_COMPARABLE reason=class_depth_or_geometry\n";
            std::cerr << text.str();
            continue;
        }
        WorkBudget work(options);
        work.ci_sample_cap = std::min(kCiSamplesPerLeaf, kCiMaximumSamples - state.kernel_evaluations);
        try {
            const CurrentElement source(snapshot.source);
            const auto roundtrip = source.frozen_input();
            const bool source_bits = std::memcmp(snapshot.source.vertices_m.data(), roundtrip.vertices_m.data(),
                    12 * sizeof(double)) == 0 &&
                std::memcmp(snapshot.source.signed_coefficients_a.data(), roundtrip.signed_coefficients_a.data(),
                    4 * sizeof(double)) == 0;
            text << "OE-F1 LEAF_DIAGNOSTIC source_roundtrip_bits=" << source_bits << '\n';
            if (!source_bits) throw std::runtime_error("source_roundtrip_mismatch");
            const std::array<int, 5> requests{{20, 22, 22, 26, 30}};
            const std::array<int, 5> expected_counts{{441, 1365, 1728, 2744, 4096}};
            const std::array<const mfem::IntegrationRule *, 5> rules{{
                &mfem::IntRules.Get(mfem::Geometry::TETRAHEDRON, requests[0]),
                &mfem::IntRules.Get(mfem::Geometry::TETRAHEDRON, requests[1]),
                &mfem::StroudIntRules.Get(mfem::Geometry::TETRAHEDRON, requests[2]),
                &mfem::StroudIntRules.Get(mfem::Geometry::TETRAHEDRON, requests[3]),
                &mfem::StroudIntRules.Get(mfem::Geometry::TETRAHEDRON, requests[4])}};
            std::uint64_t required_samples = 0;
            for (std::size_t rule_index = 0; rule_index < rules.size(); ++rule_index) {
                const auto &rule = *rules[rule_index];
                if (rule.GetNPoints() != expected_counts[rule_index]) {
                    text << "OE-F1 LEAF_DIAGNOSTIC unexpected_rule_points index=" << rule_index
                         << " points=" << rule.GetNPoints() << '\n';
                    throw std::runtime_error("rule_point_count_not_comparable");
                }
                ScalarAccumulator sum, sum_abs;
                double minimum_weight = std::numeric_limits<double>::infinity();
                bool finite = true;
                for (int sample = 0; sample < rule.GetNPoints(); ++sample) {
                    const auto &ip = rule.IntPoint(sample);
                    finite = finite && std::isfinite(ip.x) && std::isfinite(ip.y) &&
                        std::isfinite(ip.z) && std::isfinite(ip.weight);
                    sum.add(ip.weight);
                    sum_abs.add(std::abs(ip.weight));
                    minimum_weight = std::min(minimum_weight, ip.weight);
                }
                text << "OE-F1 LEAF_DIAGNOSTIC RULE index=" << rule_index
                     << " family=" << (rule_index < 2 ? "IntRules" : "StroudIntRules")
                     << " requested_order=" << requests[rule_index] << " actual_order=" << rule.GetOrder()
                     << " points=" << rule.GetNPoints() << " sum_weights=" << sum.value
                     << " sum_abs_weights=" << sum_abs.value << " min_weight=" << minimum_weight << '\n';
                if (!finite || rule.GetNPoints() != expected_counts[rule_index] ||
                        rule.GetOrder() < requests[rule_index] ||
                        std::abs(sum.value - 1.0L / 6.0L) > 1.0e-10L ||
                        (rule_index >= 2 && !(minimum_weight > 0.0))) {
                    throw std::runtime_error("rule_metadata_not_comparable");
                }
                required_samples += static_cast<std::uint64_t>(rule.GetNPoints());
            }
            if (required_samples != kCiSamplesPerLeaf || required_samples > work.ci_sample_cap) {
                throw std::runtime_error("planned_samples_not_comparable");
            }
            std::array<RuleIntegral, 5> values{};
            for (std::size_t rule_index = 0; rule_index < rules.size(); ++rule_index) {
                double minimum_distance = std::numeric_limits<double>::infinity();
                values[rule_index] = integrate_once(source, leaf.vertices, target,
                    requests[rule_index], work, rules[rule_index], &minimum_distance);
                text << "OE-F1 LEAF_DIAGNOSTIC INTEGRAL index=" << rule_index << " h_apm=";
                point(values[rule_index].value);
                text << " weighted_norm=" << values[rule_index].weighted_norm_sum
                     << " min_sample_distance_m=" << minimum_distance << '\n';
            }
            const double replay_error = norm(subtract(values[1].value, values[0].value));
            const bool high_bits = std::memcmp(values[1].value.data(), leaf.high.data(), 3 * sizeof(double)) == 0;
            const bool error_bits = std::memcmp(&replay_error, &leaf.error, sizeof(double)) == 0;
            const bool weighted_norm_match = values[0].weighted_norm_sum + values[1].weighted_norm_sum ==
                leaf.weighted_norm_sum;
            const double delta22_26 = norm(subtract(values[3].value, values[2].value));
            const double delta26_30 = norm(subtract(values[4].value, values[3].value));
            const bool stabilized = delta26_30 <= delta22_26 && delta26_30 <= options.absolute_tolerance_apm;
            text << "OE-F1 LEAF_DIAGNOSTIC COMPARISON high_bits=" << high_bits << " error_bits=" << error_bits
                 << " weighted_norm_match=" << weighted_norm_match << " replay_error_apm=" << replay_error
                 << " reference_delta22_26_apm=" << delta22_26 << " reference_delta26_30_apm=" << delta26_30
                 << " diagnostic_stability_scale_apm=" << options.absolute_tolerance_apm
                 << " old_low_vs_reference30_apm=" << norm(subtract(values[0].value, values[4].value))
                 << " old_high_vs_reference30_apm=" << norm(subtract(values[1].value, values[4].value))
                 << " status=" << (!high_bits || !error_bits || !weighted_norm_match ? "NOT_COMPARABLE_REPLAY_MISMATCH" :
                    stabilized ? "REFERENCE_STABILIZED_EMPIRICAL_NOT_CERTIFICATE" : "INCONCLUSIVE_REFERENCE_NOT_STABILIZED")
                 << '\n';
        } catch (const std::exception &error) {
            text << "OE-F1 LEAF_DIAGNOSTIC NOT_COMPARABLE exception=" << error.what() << '\n';
        }
        state.kernel_evaluations += work.kernel_evaluations;
        text << "OE-F1 LEAF_DIAGNOSTIC WORK leaf_samples=" << work.kernel_evaluations
             << " executable_samples=" << state.kernel_evaluations << " consumed_leaves=" << state.consumed_leaves
             << " per_leaf_cap=" << kCiSamplesPerLeaf << " executable_cap=" << kCiMaximumSamples << '\n';
        std::cerr << text.str();
    }
}
#endif

#ifdef FULLMAG_DTQ_CI_LEAF_DIAGNOSTIC
// Private C++ seam declared only by the CI contract, never a public C ABI.
void enable_dtq_ci_leaf_diagnostics() noexcept
{
    // Re-arming never resets the lifetime leaf or sample counters.
    ci_leaf_diagnostic_state().armed = true;
}

void consume_dtq_ci_leaf_diagnostics() noexcept
{
    try {
        replay_ci_leaf_snapshots();
    } catch (...) {
        // Diagnostics must not replace the original operator failure.
        try { std::cerr << "OE-F1 LEAF_DIAGNOSTIC NOT_COMPARABLE reason=diagnostic_exception\n"; }
        catch (...) {}
    }
}
#endif

#ifdef FULLMAG_DTQ_CI_LEAF_DIAGNOSTIC
    auto &ci_state = ci_leaf_diagnostic_state();
    if (ci_state.armed) {
        ci_state.count = 0;
        ci_state.capture_failed = false;
    }
#endif
